      INK = "#1a1a1a", LINE = "#e6e6e3", BG = "#f4f4f2", SUB = "#4a4a4a";

function T(x, y, t, o = {}) {
  return `<text x="${x}" y="${y}" fill="${o.f || INK}" font-size="${o.s || 12.5}"${o.b ? ' font-weight="700"' : ''}${o.a ? ` text-anchor="${o.a}"` : ''}>${t}</text>`;
}
function R(x, y, w, h, o = {}) {
  return `<rect x="${x}" y="${y}" width="${w}" height="${h}"${o.rx ? ` rx="${o.rx}"` : ''} fill="${o.f === undefined ? "#fff" : o.f}"${o.stroke ? ` stroke="${o.stroke}" stroke-width="${o.sw || 1}"` : ''}${o.dash ? ` stroke-dasharray="${o.dash}"` : ''}/>`;
}
function svg(body) {
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 760 460" font-family="Microsoft YaHei,PingFang SC,sans-serif">${body}</svg>`;
}
function topBar(right) {
  return R(0, 0, 760, 48, { f: "#000" }) + T(24, 30, "Mercedes-Benz · Curate", { f: "#fff", s: 14 }) +
    (right ? T(736, 30, right, { f: MUT2, s: 12, a: "end" }) : "");
}
function pill(x, y, w, h, label, fg, bg) {
  return R(x, y, w, h, { f: bg, rx: h / 2 }) + T(x + w / 2, y + h / 2 + 3.5, label, { f: fg, s: 10, a: "middle" });
}
function statusPill(x, y, label) {
  const map = { Ready: [OK, "#e8f3ec"], Building: ["#8a6d1a", "#fbf3d9"], Draft: [MUT, "#f0f0ee"], "FAILED": ["#c4392f", "#fdecea"] };
  const [fg, bg] = map[label];
