function spotlight(spot, bub, i, n, tag, lines) {
  let s = "";
  if (spot) {
    s += `<path d="M0 48 H760 V460 H0 Z M${spot[0]} ${spot[1]} h${spot[2]} v${spot[3]} h-${spot[2]} Z" fill="rgba(5,10,18,0.62)" fill-rule="evenodd"/>`;
    s += R(spot[0] - 4, spot[1] - 4, spot[2] + 8, spot[3] + 8, { f: "none", stroke: B, sw: 2, dash: "6 5", rx: 8 });
  } else {
    s += R(0, 48, 760, 412, { f: "rgba(5,10,18,0.45)" });
  }
  const h = 64 + lines.length * 20 + 34;
  s += R(bub[0], bub[1], bub[2], h, { rx: 10 });
  s += T(bub[0] + 18, bub[1] + 28, tag, { b: 1, s: 14 });
  lines.forEach((l, k) => s += T(bub[0] + 18, bub[1] + 52 + k * 20, l, { s: 12, f: SUB }));
  for (let k = 0; k < n; k++) s += `<circle cx="${bub[0] + 20 + k * 15}" cy="${bub[1] + h - 18}" r="4" fill="${k < i ? A : "#d8d8d6"}"/>`;
  s += T(bub[0] + bub[2] - 120, bub[1] + h - 14, "Skip", { s: 11, f: MUT });
  const last = i === n;
  s += R(bub[0] + bub[2] - 104, bub[1] + h - 32, 88, 26, { f: A, rx: 6 });
  s += T(bub[0] + bub[2] - 60, bub[1] + h - 14, last ? "Done ✓" : "Next →", { f: "#fff", s: 11.5, a: "middle" });
  s += T(bub[0] + bub[2] - 16, bub[1] + 26, `${i}/${n}`, { s: 11, f: MUT2, a: "end" });
  return s;
}

