Write gen.js fully."},{"type":"text","text":"Markdown 完成。重建 docx 生成脚本（含分步图，双列网格布局）:"},{"type":"tool-call","toolCallId":"todo_write_73_a2ab877b","toolName":"todo_write","args":{"merge":true,"todos":"[{"id":"3","status":"completed","content":"更新 Markdown 加入分步图"},{"id":"4","status":"in_progress","content":"重新生成 docx(含分步图)"}]"}},{"type":"tool-call","toolCallId":"write_to_file_74_27142ac6","toolName":"write_to_file","args":{"filePath":"C:\Users\mintli\AppData\Local\Temp\docxbuild2\gen.js","content":"const fs = require("fs");
const path = require("path");
const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell, ImageRun,
  AlignmentType, LevelFormat, HeadingLevel, BorderStyle, WidthType, ShadingType
} = require("docx");

const BASE = "C:\\Users\\mintli\\OneDrive - Deloitte (CN)\\Documents\\GRC-Curate-新手引导方案";
const OUT = BASE + "\\GRC-Curate-新手引导方案.docx";
const IMG = BASE + "\\images";

const border = { style: BorderStyle.SINGLE, size: 1, color: "C9C9C7" };
const borders = { top: border, bottom: border, left: border, right: border };
const cellMargins = { top: 80, bottom: 80, left: 120, right: 120 };
const warn = [];

function h1(t) { return new Paragraph({ heading: HeadingLevel.HEADING_1, children: [new TextRun(t)] }); }
function h2(t) { return new Paragraph({ heading: HeadingLevel.HEADING_2, children: [new TextRun(t)] }); }
function h3p(t) { return new Paragraph({ spacing: { before: 160, after: 60 }, children: [new TextRun({ text: t, bold: true, size: 22, color: "0078D6" })] }); }
function p(t) { return new Paragraph({ children: [new TextRun(t)] }); }
function bullet(runs, ref) {
  const children = Array.isArray(runs) ? runs : [new TextRun(runs)];
  return new Paragraph({ numbering: { reference: ref || "bullets", level: 0 }, children });
}
function bold(t) { return new TextRun({ text: t, bold: true }); }
function codeBlock(lines) {
  return lines.map(l => new Paragraph({
    shading: { fill: "F0F0EE", type: ShadingType.CLEAR },
    children: [new TextRun({ text: l, font: "Consolas", size: 18 })]
  }));
}
function table(headers, rows, widths) {
  const total = widths.reduce((a, b) => a + b, 0);
  const mkCell = (t, w, isHead) => new TableCell({
    borders, width: { size: w, type: WidthType.DXA }, margins: cellMargins,
    shading: isHead ? { fill: "F0F4F8", type: ShadingType.CLEAR } : undefined,
    children: [new Paragraph({ children: [isHead ? bold(t) : new TextRun(t)] })]
  });
  return new Table({
    width: { size: total, type: WidthType.DXA }, columnWidths: widths,
    rows: [
      new TableRow({ children: headers.map((t, i) => mkCell(t, widths[i], true)) }),
      ...rows.map(r => new TableRow({ children: r.map((t, i) => mkCell(t, widths[i], false)) }))
    ]
  });
}
function readPng(rel) {
  try { return fs.readFileSync(path.join(IMG, rel)); }
  catch (e) { warn.push(rel + ": " + e.message); return null; }
}
function img(rel, w, h, cap) {
  const data = readPng(rel.replace(/\.svg$/, ".png"));
  if (!data) return [p("【图片 " + rel + " 缺失】")];
  return [
    new Paragraph({ alignment: AlignmentType.CENTER, spacing: { before: 120 },
      children: [new ImageRun({ type: "png", data, transformation: { width: w, height: h },
        altText: { title: cap, description: cap, name: rel } })] }),
    new Paragraph({ alignment: AlignmentType.CENTER, spacing: { after: 120 },
      children: [new TextRun({ text: cap, italics: true, size: 18, color: "6A6A6A" })] })
  ];
}
// 双列分步图网格
function imgGrid(title, items) {
  const out = [h3p(title)];
  const colW = 4513, iw = 300, ih = Math.round(300 * 460 / 760);
  for (let i = 0; i < items.length; i += 2) {
    const pair = items.slice(i, i + 2);
    while (pair.length < 2) pair.push(null);
    out.push(new Table({
      width: { size: colW * 2, type: WidthType.DXA }, columnWidths: [colW, colW],
      rows: [new TableRow({ children: pair.map(it => new TableCell({
        width: { size: colW, type: WidthType.DXA }, margins: { top: 60, bottom: 60, left: 100, right: 100 },
        children: it && readPng("steps/" + it[0] + ".png") ? [
